node --input-type=module -e "
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { NextResponse, NextRequest } = require('next/server');

const req = new NextRequest('http://localhost:3000/api/test');
const requestId = crypto.randomUUID();
const requestHeaders = new Headers(req.headers);
requestHeaders.set('x-request-id', requestId);

const res = NextResponse.next({
  request: {
    headers: requestHeaders,
  },
});
res.headers.set('X-Request-Id', requestId);

console.log('res header:', res.headers.get('X-Request-Id'));
console.log('internal headers:', res.headers.get('x-middleware-request-x-request-id'));
"

node --input-type=module -e "
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { NextResponse, NextRequest } = require('next/server');

const req = new NextRequest('http://localhost:3000/hello');

// Without request headers:
const res1 = NextResponse.next();
res1.headers.set('X-Request-Id', '123');
console.log('Without request headers:', Array.from(res1.headers.entries()));

// With request headers:
const reqHeaders = new Headers(req.headers);
reqHeaders.set('x-request-id', '123');
const res2 = NextResponse.next({ request: { headers: reqHeaders } });
res2.headers.set('X-Request-Id', '123');
console.log('With request headers:', Array.from(res2.headers.entries()));
"
